import type { TransactionRecord } from "./schemas";

export interface Activity {
  id: string;
  user: string;
  action: string;
  itemName: string;
  transactionId: string;
  /** Positive = money in, negative = money out, null = no amount shown. */
  amount: number | null;
  timestamp: number;
}

/** The 20 latest actions. Rows generated by a sale (expense / fund-return / income with a unit) are skipped. */
export function buildActivity(records: readonly TransactionRecord[], limit = 20): Activity[] {
  const out: Activity[] = [];

  for (const r of records) {
    if ((r.type === "expense" || r.type === "fund-return" || r.type === "income") && r.unitId) continue;

    const itemName = r.type === "unit" ? r.name : `${r.type} transaction`;
    const push = (user: string, action: string, amount: number | null, timestamp: number, suffix: string) =>
      out.push({ id: `${r.key}:${suffix}`, user, action, itemName, transactionId: r.transactionId, amount, timestamp });

    if (r.createdBy && r.createdAt) {
      let amount: number | null = null;
      if (r.type === "unit") amount = r.cost;
      else if (r.type === "fund" || r.type === "fund-return") amount = r.amount;
      else if (r.type === "remit") amount = -r.amount;
      push(r.createdBy, `added ${r.type}`, amount, r.createdAt, "created");
    }
    if (r.type === "unit" && r.soldBy && r.soldAt) {
      push(r.soldBy, "sold unit", r.soldFor ?? null, r.soldAt, "sold");
    }
    if (r.deletedBy && r.deletedAt) push(r.deletedBy, `deleted ${r.type}`, null, r.deletedAt, "deleted");
    if (r.restoredBy && r.restoredAt) push(r.restoredBy, `restored ${r.type}`, null, r.restoredAt, "restored");
  }

  return out.sort((a, b) => b.timestamp - a.timestamp).slice(0, limit);
}
